import clsx from 'clsx';
import * as L from 'leaflet';

import getColor from '@helpers/colorsHelper';

import style from './style.module.less';
import { formatAltitude } from '../../../helpers/formatHelper';

export function setPolylineStyles(polyline: L.Polyline, styles: L.PathOptions) {
  polyline.setStyle(styles);
}

export function setMarkerPass(
  marker: L.Marker,
  mountainPass: {
    name: string;
    altitude: number;
    category: string;
  },
  inDistance = false,
) {
  const icon = L.divIcon({
    className: clsx('badge badge-danger', style.passIcon, { [style.secondaryPoint]: !inDistance }),
    html: `<span name="${mountainPass.name}" altitude="${formatAltitude(mountainPass.altitude)}">${mountainPass.category || 'н/k'}</span>`,
    iconSize: [24, 12],
    iconAnchor: [24, 6],
  });
  marker.setIcon(icon);
}

export const getDivIconByColor = (color = getColor(), temporary = false) => {
  const c = color === '#006699' ? 'inherit' : color;
  return L.divIcon({
    className: clsx('border-danger', style.simpleIcon),
    html: `<span class="${clsx(style.simpleIconCircle)}" style="border-color:${c}; color: ${c}; opacity: ${temporary ? 0.5 : 1}"></span>`,
    iconSize: [8, 8],
    iconAnchor: [4, 4],
  });
};

export function setMarkerSimpleIcon(marker: L.Marker, color?: string, temporary = false) {
  const icon = getDivIconByColor(color, temporary);
  marker.setIcon(icon);
}
